n        options: >-\n          --health-cmd="mysqladmin ping -h 127.0.0.1 -psynthetic-test-only"\n          --health-interval=10s --health-timeout=5s --health-retries=10\n    steps:\n      - uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683\n      - uses: shivammathur/setup-php@f3e473d116dcccaddc5834248c87452386958240\n        with:\n          php-version: \'8.3\'\n          extensions: pdo_sqlite, pdo_mysql\n          tools: composer:v2\n          coverage: none\n      - name: Install locked dependencies\n        working-directory: apps/web\n        run: composer install --no-interaction --no-progress --prefer-dist\n      - name: Real SQL activation, canonical credential verification, queue and feedback\n        run: |\n          set -euo pipefail\n          php apps/web/tests/platform-dsn.php\n          php apps/web/tests/control-plane-enterprise.php\n          PLATFORM_TEST_ENGINE=mysql php apps/web/tests/control-plane-enterprise.php\n          php apps/web/tests/merchant-context-atomic-bootstrap.php\n          php apps/web/tests/business-role-administration.php\n          php apps/web/tests/privileged-reauthentication-step-up.php\n      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e\n        with:\n          node-version: 24.19.0\n      - name: Type check and compile bilingual control plane\n        working-directory: apps/web\n        run: |\n          npm ci --ignore-scripts --no-fund\n          npm run type-check\n          npm run build\n      - name: Exercise compiled control plane, stable retries, activation and mobile layouts\n        run: |\n          npm install --prefix "$RUNNER_TEMP/oneqay-platform-browser" --ignore-scripts --no-audit --no-fund playwright@1.62.1\n          node "$RUNNER_TEMP/oneqay-platform-browser/node_modules/playwright/cli.js" install --with-deps --only-shell chromium\n          PLAYWRIGHT_MODULE="$RUNNER_TEMP/oneqay-platform-browser/node_modules/playwright/index.mjs" node tools/qa-platform-owner-ui.mjs\n      - name: Publish compiled review artifact\n        if: always()\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02\n        with:\n          name: platform-owner-mail-${{ github.event.pull_request.head.sha || github.sha }}\n          path: |\n            apps/web/public/build\n            dist/platform-ui-qa\n          if-no-files-found: ignore\n          retention-days: 7\n', '# Author by Lab | zefry\nname: Platform Owner and Reliable Mail\non:\n  pull_request:\n    branches: [main]\n  workflow_dispatch:\npermissions:\n  contents: read\njobs:\n  platform-owner-mail:\n    runs-on: ubuntu-latest\n    timeout-minutes: 20\n    services:\n      mysql:\n        image: mysql:8.4\n        env:\n          MYSQL_ROOT_PASSWORD: synthetic-test-only\n          MYSQL_DATABASE: oneqay_platform_test\n        ports: [\'3306:3306\']\n        options: >-\n          --health-cmd="mysqladmin ping -h 127.0.0.1 -psynthetic-test-only"\n          --health-interval=10s --health-timeout=5s --health-retries=10\n    steps:\n      - uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683\n      - uses: shivammathur/setup-php@f3e473d116dcccaddc5834248c87452386958240\n        with:\n          php-version: \'8.3\'\n          extensions: pdo_sqlite, pdo_mysql\n          tools: composer:v2\n          coverage: none\n      - name: Install locked dependencies\n        working-directory: apps/web\n        run: composer install --no-interaction --no-progress --prefer-dist\n      - name: Real SQL activation, canonical credential verification, queue and feedback\n        run: |\n          set -euo pipefail\n          php apps/web/tests/platform-dsn.php\n          php apps/web/tests/platform-control-mail.php\n          PLATFORM_TEST_ENGINE=mysql php apps/web/tests/platform-control-mail.php\n          php apps/web/tests/merchant-context-atomic-bootstrap.php\n          php apps/web/tests/business-role-administration.php\n          php apps/web/tests/privileged-reauthentication-step-up.php\n      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e\n        with:\n          node-version: 24.19.0\n      - name: Type check and compile bilingual control plane\n        working-directory: apps/web\n        run: |\n          npm ci --ignore-scripts --no-fund\n          npm run type-check\n          npm run build\n      - name: Exercise compiled control plane, stable retries, activation and mobile layouts\n        run: |\n          npm install --prefix "$RUNNER_TEMP/oneqay-platform-browser" --ignore-scripts --no-audit --no-fund playwright@1.62.1\n          node "$RUNNER_TEMP/oneqay-platform-browser/node_modules/playwright/cli.js" install --with-deps --only-shell chromium\n          PLAYWRIGHT_MODULE="$RUNNER_TEMP/oneqay-platform-browser/node_modules/playwright/index.mjs" node tools/qa-platform-owner-ui.mjs\n      - name: Publish compiled review artifact\n        if: always()\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02\n        with:\n          name: platform-owner-mail-${{ github.event.pull_request.head.sha || github.sha }}\n          path: |\n            apps/web/public/build\n            dist/platform-ui-qa\n          if-no-files-found: ignore\n          retention-days: 7\n']], '.github/workflows/production-business-release-certification.yml': [['# Author by Lab | zefry\nname: Production Business Release Certification\n\non:\n  pull_request:\n    branches: [main]\n  push:\n    branches: [main]\n    paths:\n      - \'apps/web/**\'\n      - \'tools/build-production-business-release.sh\'\n      - \'tools/validate-production-business-release-manifest.php\'\n      - \'tools/production/tests/production-business-release-source-certification.php\'\n      - \'release/production-business-manifest-v2.schema.json\'\n      - \'.github/workflows/production-business-release-certification.yml\'\n  workflow_dispatch:\n\npermissions:\n  contents: read\nconcurrency:\n  group: production-business-source-cert-${{ github.ref }}-${{ github.sha }}\n  cancel-in-progress: false\n\njobs:\n  certify:\n    runs-on: ubuntu-latest\n    timeout-minutes: 90\n    env:\n      APP_NAME: oneQay\n      APP_ENV: testing\n      APP_KEY: base64:YWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWE=\n      APP_DEBUG: \'false\'\n      APP_URL: http://localhost\n      ONEQAY_RUNTIME_CLASS: ci\n      SESSION_DRIVER: array\n      CACHE_STORE: array\n      LOG_CHANNEL: stderr\n    steps:\n      - name: Checkout immutable source commit\n        uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683\n        with:\n          fetch-depth: 0\n          ref: ${{ github.event.pull_request.head.sha || github.sha }}\n      - name: PHP 8.3 and isolated database extensions\n        uses: shivammathur/setup-php@f3e473d116dcccaddc5834248c87452386958240\n        with:\n          php-version: \'8.3\'\n          extensions: pdo_mysql,pdo_sqlite,mbstring,openssl,phar\n          tools: composer:v2\n          coverage: none\n      - name: Node 24.19\n        uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e\n        with:\n          node-version: 24.19.0\n      - name: Enforce exact oneQayDev Production source envelope\n        if: github.event_name == \'pull_request\' && github.head_ref == \'production-dev-readiness-and-merchant-foundation-20261010\'\n        env:\n          BASE_SHA: ${{ github.event.pull_request.base.sha }}\n        run: |\n          set -euo pipefail\n          git diff --name-only "$BASE_SHA" HEAD -- apps/web | LC_ALL=C sort > /tmp/oneqaydev-authorized-app-paths\n          diff -u ops/production/ONEQAYDEV_READINESS_MERCHANT_AUTHORIZED_APP_PATHS.txt /tmp/oneqaydev-authorized-app-paths\n          test -z "$(git diff --name-only "$BASE_SHA" HEAD -- apps/web/database/migrations)"\n          test -z "$(git diff --name-only "$BASE_SHA" HEAD -- apps/web/composer.json apps/web/composer.lock apps/web/package.json apps/web/package-lock.json)"\n          test ! -e apps/web/.env\n          grep -Fq "ProductionMerchantProvisioningScope::allows" apps/web/app/Infrastructure/Bootstrap/LaravelMerchantContextBootstrapStateRepository.php\n          grep -Fq "ProductionMerchantProvisioningScope::allows" apps/web/app/Infrastructure/Identity/LaravelFirstControlPrincipalCredentialBootstrapRepository.php\n          grep -Fq \'business_runtime_activation_ready\' apps/web/app/Infrastructure/Runtime/ProductionBusinessRuntimeGate.php\n          grep -Fq \'production_traffic_activation_authorized":false\' tools/build-production-business-release.sh\n          git diff --name-only "$BASE_SHA" HEAD -- .github/workflows | grep -v \'^.github/workflows/production-business-release-certification.yml$\' | LC_ALL=C sort > /tmp/oneqaydev-authorized-workflows\n          diff -u ops/production/ONEQAYDEV_READINESS_MERCHANT_AUTHORIZED_WORKFLOW_PATHS.txt /tmp/oneqaydev-authorized-workflows\n          while IFS= read -r historical; do\n            git diff --unified=0 "$BASE_SHA" HEAD -- "$historical" > /tmp/oneqaydev-workflow-diff\n            if grep -E \'^[+-][^+-]\' /tmp/oneqaydev-workflow-diff | grep -Ev \'^[+-] *if: \' ; then\n              echo "Refusing non-condition modification to preserved workflow: $historical" >&2\n              exit 1\n            fi\n            grep -Fq \'production-dev-readiness-and-merchant-foundation-20261010\' "$historical"\n          done < /tmp/oneqaydev-authorized-workflows\n          echo "oneqaydev exact source envelope verified; historical source-envelope steps superseded only for this exact PR"\n\n      - name: Check successor source, schema, and denied substitutions\n        run: |\n          set -euo pipefail\n          bash -n tools/build-production-business-release.sh\n          php -l tools/validate-production-business-release-manifest.php\n          php -l tools/production/tests/production-business-release-source-certification.php\n          php -r \'json_decode(file_get_contents("release/production-business-manifest-v2.schema.json"), true, 64, JSON_THROW_ON_ERROR);\'\n          php -l apps/web/app/Console/Commands/ProductionFirstMerchantProvisionCommand.php\n          php -l apps/web/app/Infrastructure/Bootstrap/ProductionMerchantProvisioningScope.php\n          php tools/production/tests/production-business-release-source-certification.php\n          grep -Fq \'"business_runtime_activation_ready":false\' tools/build-production-release.sh\n          grep -Fq \'"business_runtime_activation_ready":true\' tools/build-production-business-release.sh\n          grep -Fq \'production_traffic_activation_authorized":false\' tools/build-production-business-release.sh\n          test "$(find apps/web/database/migrations -maxdepth 1 -name \'*.php\' | wc -l)" -eq 27\n      - name: Install locked Laravel and front-end dependencies\n        run: |\n          set -euo pipefail\n          cd apps/web\n          composer validate --no-check-publish\n          composer install --no-interaction --prefer-dist --no-progress\n          npm ci --ignore-scripts --no-fund\n          npm run type-check\n          npm run build\n      - name: Verify cPanel disabled-link capabilities and bounded workspace recovery\n        run: |\n          set -euo pipefail\n          php -l tools/production/cpanel/recover-oneqaydev-certified-workspace.php\n          php -d zend.assertions=1 -d assert.exception=1 tools/production/tests/oneqaydev-certified-workspace-update.php\n          php tools/production/tests/oneqaydev-workspace-cpanel-link.php\n          php -d disable_functions=symlink tools/production/tests/oneqaydev-workspace-cpanel-link.php\n          php -d disable_functions=link tools/production/tests/oneqaydev-workspace-cpanel-link.php\n          php -d disable_functions=link,symlink tools/production/tests/oneqaydev-workspace-cpanel-link.php\n      - name: Verify business-on workspace update and rollback boundaries\n        if: github.event_name == \'pull_request\' && github.head_ref == \'oneqaydev-enterprise-workspace-